<script setup>
import { computed, ref, shallowRef } from 'vue'
import { readShapefileZip } from './shapefile.js'
import { zipFiles } from '../shared/archive.js'
import { downloadFile } from '../shared/download.js'

const source = shallowRef(null)
const loading = ref(false),
  exporting = ref(false),
  error = ref(''),
  result = ref('')
const busy = computed(() => loading.value || exporting.value)
async function loadZip(selected) {
  error.value = ''
  result.value = ''
  source.value = null
  const file = Array.isArray(selected) ? selected[0] : selected
  if (!file) return
  loading.value = true
  try {
    source.value = { name: file.name, buffer: await file.arrayBuffer() }
  } catch (failure) {
    error.value = `Could not read ZIP: ${failure.message}`
  } finally {
    loading.value = false
  }
}
async function exportGeoJson() {
  if (!source.value || busy.value) return
  error.value = ''
  result.value = ''
  exporting.value = true
  try {
    const layers = await readShapefileZip(source.value.buffer)
    const stem = source.value.name.replace(/\.[^.]+$/, '')
    const filename = layers.length === 1 ? stem + '.geojson' : stem + '_geojson.zip'
    if (layers.length === 1) downloadFile(JSON.stringify(layers[0].collection), filename)
    else
      downloadFile(
        await zipFiles(layers.map((layer) => ({ name: layer.name, content: JSON.stringify(layer.collection) }))),
        filename,
        'application/zip',
      )
    result.value = `${layers.length} layers, ${layers.reduce((sum, layer) => sum + layer.collection.features.length, 0)} features exported. Downloaded: ${filename}.`
  } catch (failure) {
    error.value = `Could not convert Shapefile: ${failure.message}`
  } finally {
    exporting.value = false
  }
}
const fileUpload = ref()
</script>

<template>
  <!-- Bố cục: VaCard chứa đầu vào ZIP shapefile, tiến độ đọc và nút xuất GeoJSON; các thông báo thành công/lỗi nằm ngoài form. -->
  <section>
    <h1 class="page-title">SHP → GeoJSON</h1>
    <VaCard>
      <VaCardContent>
        <!-- Đầu vào và cấu hình xuất dùng control Vuestic; submit gọi hàm xử lý của trang, busy khóa thao tác khi đang chạy. -->
        <VaForm novalidate class="space-y-4" @submit.prevent="exportGeoJson">
          <VaFileUpload
            id="shp-zip-file"
            v-model="fileUpload"
            type="single"
            upload-button-text="Shapefile ZIP"
            file-types=".zip,application/zip"
            :disabled="busy"
            @update:modelValue="loadZip"
          />
          <VaProgressBar v-if="loading" indeterminate aria-label="Reading file" />
          <VaButton type="submit" color="primary" :disabled="!source || busy" :loading="exporting"
            >Export GeoJSON</VaButton
          >
        </VaForm>
        <!-- Thông báo đọc/xuất dữ liệu nằm gần thao tác liên quan; điều kiện v-if quyết định lúc hiển thị. -->
        <VaAlert v-if="error" color="danger" class="mt-4" role="alert" data-testid="tool-error">{{ error }}</VaAlert>
        <VaAlert v-if="result" color="success" class="mt-4" role="status" data-testid="tool-result">{{
          result
        }}</VaAlert>
      </VaCardContent>
    </VaCard>
  </section>
</template>
